    const currentValue = opts.get();
    const onText = opts.onLabel ?? "On";
    const offText = opts.offLabel ?? "Off";
    const setting = new import_obsidian5.Setting(opts.container).setName(opts.name);
    if (isEditing) {
      setting.setDesc(opts.desc);
      let draft = currentValue;
      setting.addToggle((t) => {
        t.setValue(currentValue).setDisabled(Boolean(opts.disabled));
        t.onChange((v2) => {
          draft = v2;
        });
      });
      setting.addButton(
        (b2) => b2.setButtonText("Save").setCta().onClick(async () => {
          opts.set(draft);
          await this.plugin.saveSettings();
          this.editing.delete(opts.key);
          this.display();
        })
      );
      setting.addButton(
        (b2) => b2.setButtonText("Cancel").onClick(() => {
          this.editing.delete(opts.key);
          this.display();
        })
      );
    } else {
      const valueEl = setting.controlEl.createSpan({
        cls: "pericode-locked-value",
        text: currentValue ? onText : offText
      });
      valueEl.style.fontFamily = "var(--font-monospace)";
      valueEl.style.color = currentValue ? "var(--text-success)" : "var(--text-muted)";
      valueEl.style.marginRight = "12px";
      setting.addButton(
        (b2) => b2.setButtonText("Edit").setDisabled(Boolean(opts.disabled)).onClick(() => {
          if (opts.disabled) return;
          this.editing.add(opts.key);
          this.display();
        })
      );
    }
